#include <vector>
#include <atomic>
#include <mutex>

class ShardQueue {
public:
    explicit ShardQueue(size_t n) : shards_(n) {}

    void push(Task&& t) {
        auto& q = shards_[std::hash<std::thread::id>{}(std::this_thread::get_id()) % shards_.size()];
        std::lock_guard<std::mutex> lk(q.mtx);
        q.tasks.push_back(std::move(t));
    }

